"use client";

import { useTransition } from "react";
import { MoreVertical, Trash2, Loader2 } from "lucide-react";
import { deleteSession } from "./actions";
import { ActionDropdown } from "../../../../components/ui/ActionDropdown";

export function SessionRowActions({ sessionId }: { sessionId: string }) {
  const [isPending, startTransition] = useTransition();

  const handleDelete = () => {
    if (window.confirm("Are you sure you want to delete this session? All attendance records will also be deleted. This cannot be undone.")) {
      startTransition(async () => {
        const res = await deleteSession(sessionId);
        if (res.error) alert(res.error);
      });
    }
  };

  return (
    <ActionDropdown
      disabled={isPending}
      trigger={isPending ? <Loader2 className="w-4 h-4 animate-spin text-indigo-500" /> : <MoreVertical className="w-4 h-4" />}
      items={[
        {
          label: "Delete Session",
          icon: <Trash2 />,
          onClick: handleDelete,
          danger: true
        }
      ]}
    />
  );
}
